-- Small fixture for scripts/e2e_diff.py (PostgreSQL 15+). Runs in a throwaway database.
-- Roles and the storage stub are what check.sql expects on a Supabase project.

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'anon') THEN
    CREATE ROLE anon NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'authenticated') THEN
    CREATE ROLE authenticated NOLOGIN;
  END IF;
END
$$;

CREATE SCHEMA storage;
CREATE TABLE storage.buckets (id text PRIMARY KEY, name text NOT NULL, public boolean NOT NULL DEFAULT false);

-- rls_disabled (High): present in every run, so it must show up as "unchanged" in the diff.
CREATE TABLE public.todos (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title text NOT NULL
);

-- Control: RLS enabled, no policy for anon. Never produces a finding.
CREATE TABLE public.profiles_private (
  id uuid PRIMARY KEY,
  owner_id uuid NOT NULL
);
ALTER TABLE public.profiles_private ENABLE ROW LEVEL SECURITY;

-- The name does not match the sensitive-table pattern, so the anon policy below produces no
-- sensitive_anon_policy finding until the table is tagged with COMMENT ON TABLE ... IS 'pii'.
CREATE TABLE public.journal_entries (
  id uuid PRIMARY KEY,
  entry text NOT NULL
);
ALTER TABLE public.journal_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY anon_journal ON public.journal_entries
  FOR SELECT TO anon
  USING (entry IS NOT NULL);

-- Control: also readable by anon and also not named sensitive, but it never gets tagged.
CREATE TABLE public.countries (
  code text PRIMARY KEY,
  name text NOT NULL
);
ALTER TABLE public.countries ENABLE ROW LEVEL SECURITY;
CREATE POLICY anon_countries ON public.countries
  FOR SELECT TO anon
  USING (code IS NOT NULL);
